window.VO = [{"id":"n01","text":"You're looking at someone drowning.","at":0.1,"t0":0.05,"t1":1.535},{"id":"n02","text":"Fifteen seconds.","at":3.77,"t0":1.885,"t1":3},{"id":"n03","text":"Find them.","at":6.4,"t0":3.2,"t1":3.9},{"id":"c01","text":"Help!","at":8.6,"t0":4.3,"t1":4.93},{"id":"c02","text":"Hey! Over here!","at":14.83,"t0":7.415,"t1":8.57},{"id":"n04","text":"Halfway.","at":18.13,"t0":9.065,"t1":9.82},{"id":"n05","text":"Last chance.","at":28.43,"t0":14.215,"t1":15.11},{"id":"n06","text":"Time.","at":33.81,"t0":16.905,"t1":17.535},{"id":"n07","text":"It's number nine.","at":36.17,"t0":18.085,"t1":19.11},{"id":"n08","text":"She hasn't made a sound, and she keeps going under.","at":38.72,"t0":19.36,"t1":22.045},{"id":"n09","text":"Did you go for the noise?","at":45.29,"t0":22.645,"t1":23.92},{"id":"n10","text":"The boy was playing, and the man was waving at a boat.","at":48.34,"t0":24.17,"t1":26.995},{"id":"n11","text":"If you found her, you saw what her friends didn't.","at":55.09,"t0":27.545,"t1":30.05},{"id":"n12","text":"They're right there.","at":60.4,"t0":30.2,"t1":31.105},{"id":"c03","text":"Maya?","at":63.11,"t0":31.555,"t1":32.16},{"id":"c04","text":"Maya!","at":65.42,"t0":32.71,"t1":33.295},{"id":"c05","text":"Help!","at":67.29,"t0":33.645,"t1":34.24},{"id":"n13","text":"She can't shout or wave: there's only time to breathe, and both arms are pushing her mouth up.","at":70.18,"t0":35.09,"t1":40.205},{"id":"n14","text":"So don't wait for a shout.","at":81.61,"t0":40.805,"t1":42.135},{"id":"n15","text":"If you're not sure, call for help anyway.","at":84.67,"t0":42.335,"t1":44.4},{"id":"n16","text":"Now look.","at":95.3,"t0":47.65,"t1":48.39}];
